def make_description(name: str, kind: str, domains: str, summary: str, note: str, see_also: str) -> str:
    return "\n\n".join(
        [
            summary,
            note,
            (
                f"辞書的には、{name}は「{kind}」として引ける項目で、主な属性は「{domains}」。"
                "単なる名前ではなく、どの宗教圏・物語圏で、どの役割を持つかを合わせて読むと分かりやすい。"
            ),
            (
                "アブラハム系・イスラム・アラビア・ペルシア周辺の語は、聖典、外典、民間伝承、後世の文学が重なりやすい。"
                "そのため、正典上の人物や概念なのか、民間伝承上の怪物なのか、神秘思想や叙事詩の語なのかを分けておくと辞典として扱いやすい。"
            ),
            (
                f"関連語としては「{see_also}」を合わせて見るとよい。"
                "人物なら系譜や対立関係、土地なら移動や試練、天使・悪魔なら役割や属性、終末論なら出来事の順序をたどる入口になる。"
            ),
            (
                "世界観設定で使う場合は、名称だけでなく、象徴、禁忌、出現場所、信仰・儀礼との結びつき、似た存在との差をメモしておくと検索しやすい。"
                "特に天使、ジン、終末、聖地、聖遺物は他神話の近い概念とも比較しやすい。"
            ),
        ]
    )


def term(
    name: str,
    aliases: str,
    mythology: str,
    kind: str,
    domains: str,
    summary: str,
    note: str | None = None,
    see_also: str | None = None,
    *,
    language: str = "Arabic, Hebrew, Greek, Persian",
    tags: str = "",
) -> dict[str, str]:
    if see_also is None:
        see_also = note or ""
        note = summary
        summary = domains
        domains = kind
        kind = mythology
        mythology = "キリスト教/聖書"

    return {
        "term": name,
        "reading": "",
        "aliases": aliases,
        "language": language,
        "kind": kind,
        "mythology": mythology,
        "domains": domains,
        "tags": merge_multi_values("アブラハム, 中東伝承", tags, TAG),
        "summary": summary,
        "description": make_description(name, kind, domains, summary, note or "", see_also or ""),
        "see_also": see_also or "",
        "sources": SOURCE_NOTE,
    }


