def merge_entry(existing: dict[str, Any], incoming: dict[str, str]) -> dict[str, str]:
    merged = {field: str(existing.get(field, "")) for field in ENTRY_FIELDS}
    for field, value in incoming.items():
        if not value:
            continue
        if field in {"aliases", "domains", "tags", "see_also", "sources"}:
            merged[field] = merge_multi_values(existing.get(field, ""), value)
        else:
            merged[field] = value
    return merged


def main() -> None:
    if DB_PATH.exists() and not BACKUP_PATH.exists():
        shutil.copy2(DB_PATH, BACKUP_PATH)

    results = {"created": [], "updated": []}
    for item in TERMS:
        matches = find_entries_by_term(item["term"], DB_PATH)
        if matches:
            entry_id = matches[0]["id"]
            update_entry(entry_id, merge_entry(matches[0], item), DB_PATH)
            results["updated"].append({"id": entry_id, "term": item["term"], "data": item})
        else:
            entry_id = create_entry(item, DB_PATH)
            results["created"].append({"id": entry_id, "term": item["term"], "data": item})

    OUT_PATH.write_text(json.dumps(results, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"created={len(results['created'])}")
    print(f"updated={len(results['updated'])}")
    print(f"backup={BACKUP_PATH}")
    print(f"wrote={OUT_PATH}")


if __name__ == "__main__":
    main()
